<?php
declare(strict_types=1);
return static function(PDO$pdo):void{
    $pdo->exec("ALTER TABLE program_manuals ADD COLUMN supersedes_manual_id INT NULL AFTER program_specification_id,ADD COLUMN declared_program_name VARCHAR(255) NULL AFTER academic_period,ADD COLUMN declared_credit_hours INT NULL AFTER declared_program_name,ADD COLUMN declared_semesters INT NULL AFTER declared_credit_hours,ADD COLUMN declared_plo_count INT NULL AFTER declared_semesters,ADD COLUMN declared_course_count INT NULL AFTER declared_plo_count,ADD KEY idx_program_manual_supersedes(supersedes_manual_id),ADD CONSTRAINT fk_program_manual_supersedes FOREIGN KEY(supersedes_manual_id) REFERENCES program_manuals(id) ON DELETE SET NULL");
    $pdo->exec("CREATE TABLE program_manual_reconciliations (id INT AUTO_INCREMENT PRIMARY KEY,program_manual_id INT NOT NULL,field_key VARCHAR(100) NOT NULL,specification_value TEXT NULL,manual_value TEXT NULL,resolution ENUM('Unresolved','Accept Specification','Accept Manual','Keep Both') NOT NULL DEFAULT 'Unresolved',explanation TEXT NULL,resolved_by_user_id INT NULL,resolved_at DATETIME NULL,created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,UNIQUE KEY uq_manual_reconciliation(program_manual_id,field_key),KEY idx_manual_resolution(resolution),CONSTRAINT fk_manual_reconciliation_manual FOREIGN KEY(program_manual_id) REFERENCES program_manuals(id) ON DELETE CASCADE,CONSTRAINT fk_manual_reconciliation_user FOREIGN KEY(resolved_by_user_id) REFERENCES users(id) ON DELETE SET NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci");
};
